def _build_prompt(document_text: str, fields: Optional[Iterable[str]]) -> str:
    field_list = list(fields or [])
    fields_part = ""
    if field_list:
        fields_part = "\nExpected fields: " + ", ".join(field_list)
    return (
        "Extract structured fields from the document text. "
